from fractions import Fraction
import math
from collections import deque

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve_reachability_constrained(m, n, max_elements=12, max_depth=4):
    """
    Checks if 1 is reachable from {m/n, n/m} using AM or HM within constraints.
    """
    if m == n:
        return True 

    initial_numbers = {Fraction(m, n), Fraction(n, m)}

    if Fraction(1) in initial_numbers:
        return True

    # Queue stores (current_set_of_numbers, current_depth)
    queue = deque([(frozenset(initial_numbers), 0)])
    visited = {frozenset(initial_numbers)}

    while queue:
        current_set_frozen, depth = queue.popleft()
        current_set = set(current_set_frozen)

        if depth >= max_depth:
            continue

        new_numbers = set()
        numbers_list = list(current_set)

        # Generate all possible new numbers
        for i in range(len(numbers_list)):
            for j in range(i, len(numbers_list)):
                x = numbers_list[i]
                y = numbers_list[j]

                # AM: (x+y)/2
                am = (x + y) / 2
                new_numbers.add(am)

                # HM: 2xy / (x+y)
                if x + y != 0:
                    hm = 2 * x * y / (x + y)
                    new_numbers.add(hm)


        for new_num in new_numbers:
            if new_num == 1:
                return True

            if new_num not in current_set:
                next_set = current_set.union({new_num})
                next_set_frozen = frozenset(next_set)

                if len(next_set) <= max_elements and next_set_frozen not in visited:
                    visited.add(next_set_frozen)
                    queue.append((next_set_frozen, depth + 1))

    return False

# --- Test cases generation ---

successful_pairs = []
max_sum = 20

for m in range(1, max_sum // 2):
    for n in range(m + 1, max_sum):
        if gcd(m, n) == 1:
            if solve_reachability_constrained(m, n):
                successful_pairs.append((m, n))

print("--- Results ---")
print(f"Pairs (m, n) with m < n and m+n < {max_sum} that allow reaching 1 (within depth/element limits): {successful_pairs}")

